# The repeat statuses' old values, named for watching, and their neutral ones
RENAMED_STATUSES = {"Rewatching": "Repeating", "Planning rewatch": "Planning repeat"}

MEDIA_MODELS = (
    "anime",
    "basicmedia",
    "boardgame",
    "book",
    "comic",
    "game",
    "manga",
    "movie",
    "season",
    "tv",
)


def rename_statuses(apps, mapping):
    """Rename the given status values on all media and their history."""
    for name in MEDIA_MODELS:
        for model_name in (name, f"historical{name}"):
            model = apps.get_model("app", model_name)
            for old, new in mapping.items():
                model.objects.filter(status=old).update(status=new)


def forwards(apps, schema_editor):
    """Give the repeat statuses their neutral values."""
    rename_statuses(apps, RENAMED_STATUSES)


def backwards(apps, schema_editor):
    """Give the repeat statuses back their old values."""
    rename_statuses(apps, {new: old for old, new in RENAMED_STATUSES.items()})


